/// Twice the supervisor's reply budget (`queues::MAX_REPLIES`, 1024) in frames: Spawned + Exited per tree.
const BURST: usize = 1024;

/// `hostname.exe`: a program that starts and ends at once.
fn quick() -> Spec {
    let root: OsString = std::env::var_os("SystemRoot").unwrap();
    let mut spec = Spec::program(&PathBuf::from(&root).join(r"System32\hostname.exe"), &[]);
    spec.stderr = Slot::Merge;
    spec.env = vec![("SystemRoot".into(), root)];
    spec

#[test]
fn a_burst_to_a_host_that_does_not_read_is_delivered_and_service_resumes() {
    let mut host = Host::start();
    let (mut frames, mut reqs) = (Vec::new(), Vec::new());
    for _ in 0..BURST {
        // The host's read end goes with `p`: a child may fail its write, which changes nothing here.
        let p = host.prepare(quick());
        reqs.push(p.req);
        frames.extend(host::frame(&p.msg));
    }
    // The host writes every Spawn and reads nothing: Spawned and Exited frames pile up in the supervisor until
    // it stops admitting requests, and the host's write stalls.
    let writer = host.writer();
    let (stalled_tx, stalled) = mpsc::channel();
    let w = std::thread::spawn(move || {
        writer.write(&frames, Duration::from_secs(1), move || {
            let _ = stalled_tx.send(());
        })
    });
    // ~2048 reply frames against 4 KiB of host-side buffering and a budget of 1024: the supervisor must stop
    // admitting, and so stop reading, before the host has written everything.
    assert!(
        stalled.recv_timeout(Duration::from_secs(60)).is_ok(),
        "the host was never held back"
    );
    // The host reads again: every request gets its reply, every tree its Exited.
    let mut ids = Vec::new();
    for &req in &reqs {
        match host.reply(req) {
            Msg::Spawned { id, .. } => ids.push(id),
            other => panic!("{other:?}"),
        }
    }
    for &id in &ids {
        host.exited(id);
    }
    w.join().unwrap();
    // Service resumed: new requests complete.
    host.stop(ids[0], 0);
    let released = host.call(|req| Msg::Release { req, id: ids[0] });
    assert!(matches!(released, Msg::Ack { result: Ack::Ok, .. }), "{released:?}");
    assert!(host.spawn(quick()).is_ok());

/// Runs one mode and exits:
/// - `argv <args>`: prints its raw command line, its arguments, cwd and `HUGR_W06`;
/// - `stdin`: reads stdin to EOF, prints the handle's file type and the byte count;
/// - `both`: `OUT` on stdout, `ERR` on stderr;
/// - `job`: prints its own Job's member count and limits, and whether a breakaway child was refused;
/// - `exit <code>`;
/// - `chain <level> <depth> <resist> <root-exits>`: a chain of descendants; each prints `PID <level> <pid>`,
///   the root prints `READY` (or exits, if asked); `resist` ignores CTRL_BREAK/C/CLOSE; all hang;
/// - `breed <log>`: prints `READY`; on CTRL_BREAK starts hanging descendants until it is killed, appending
///   `<pid> <creation time>` to `log` (one write) for each one as soon as it exists;
/// - `nest`: puts itself in a Job of its own (nested in the supervisor's), then runs `chain 0 2 0 0`.
pub fn run(args: &[OsString]) -> ! {
    let words: Vec<&str> = args.iter().map(|a| a.to_str().unwrap_or("")).collect();
    match words.as_slice() {
        ["argv", ..] => {
            // SAFETY: GetCommandLineW returns this process's NUL-terminated command line.
            let raw = unsafe {
                let p = GetCommandLineW();
                OsString::from_wide(std::slice::from_raw_parts(
                    p,
                    (0..).take_while(|&i| *p.add(i) != 0).count(),
                ))
            };
            out(&format!("CMDLINE {raw:?}"));
            out(&format!("ARGS {:?}", &args[1..]));
            out(&format!("CWD {:?}", std::env::current_dir().unwrap()));
            out(&format!("ENV {:?}", std::env::var_os("HUGR_W06")));
        }
        ["stdin"] => {
            // SAFETY: plain queries on this process's stdin.
            let kind = unsafe { GetFileType(GetStdHandle(STD_INPUT_HANDLE)) };
            let mut buf = Vec::new();
            std::io::stdin().read_to_end(&mut buf).unwrap();
            out(&format!("STDIN kind={kind} bytes={}", buf.len()));
        }
        ["both"] => {
            out("OUT");
            eprintln!("ERR");
        }
        ["job"] => job(),
        ["exit", code] => std::process::exit(code.parse::<u32>().unwrap() as i32),
        ["chain", level, depth, resist, root_exits] => chain(level.parse().unwrap(), depth, resist, root_exits),
        ["breed", log] => breed(log),
        ["nest"] => {
            // A Job of its own inside the supervisor's, as cargo makes one: its descendants are in both.
            // SAFETY: an anonymous Job and the current-process pseudo handle; the Job handle is kept open.
            unsafe {
                let job = CreateJobObjectW(std::ptr::null(), std::ptr::null());
                assert!(!job.is_null());
                assert_ne!(AssignProcessToJobObject(job, GetCurrentProcess()), 0);
            }
            chain(0, "2", "0", "0")
        }
        other => panic!("unknown child mode {other:?}"),
    }
    std::process::exit(0)

fn job() {
    let mut acct = JOBOBJECT_BASIC_ACCOUNTING_INFORMATION::default();
    let mut lim = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
    let null = std::ptr::null_mut();
    // SAFETY: a null Job is the caller's innermost Job; each structure matches its class and size.
    unsafe {
        let n = size_of_val(&acct) as u32;
        assert_ne!(
            QueryInformationJobObject(
                null,
                JobObjectBasicAccountingInformation,
                (&raw mut acct).cast(),
                n,
                null.cast()
            ),
            0
        );
        let n = size_of_val(&lim) as u32;
        assert_ne!(
            QueryInformationJobObject(
                null,
                JobObjectExtendedLimitInformation,
                (&raw mut lim).cast(),
                n,
                null.cast()
            ),
            0
        );
    }
    let flags = lim.BasicLimitInformation.LimitFlags;
    let escape = match child_cmd(&["exit", "0"])
        .creation_flags(CREATE_BREAKAWAY_FROM_JOB)
        .status()
    {
        Ok(_) => "escaped".to_string(),
        Err(e) => format!("refused:{}", e.raw_os_error().unwrap_or(0)),
    };
    out(&format!(
        "JOB active={} kill={} breakaway={} escape={escape}",
        acct.ActiveProcesses,
        flags & JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE != 0,
        flags & (JOB_OBJECT_LIMIT_BREAKAWAY_OK | JOB_OBJECT_LIMIT_SILENT_BREAKAWAY_OK) != 0
    ));

/// The barrier: nothing is started before the graceful stop's CTRL_BREAK arrives; from then on descendants
/// (hanging `chain`s) are started one after another until the Job is terminated. Each one is logged here as
/// soon as it exists, never by itself: on a slow machine the descendants of this unthrottled loop may never
/// get to run before the deadline (W06b: 875 created, 46 started, on GitLab's 2-vCPU runner), and the oracle
/// must cover the ones the Job's termination caught still starting.
fn breed(log: &str) -> ! {
    // SAFETY: a handler that lives as long as the process.
    unsafe { SetConsoleCtrlHandler(Some(start_breeding), 1) };
    let log = log.to_string();
    std::thread::spawn(move || {
        drop(BREAK.wait_while(BREAK_SEEN.lock().unwrap(), |seen| !*seen).unwrap());
        let mut file = std::fs::OpenOptions::new()
            .append(true)
            .create(true)
            .open(&log)
            .unwrap();
        while let Ok(mut c) = child_cmd(&["chain", "0", "0", "0", "0"]).stdout(Stdio::null()).spawn() {
            let line = format!("{} {}\n", c.id(), created(c.as_raw_handle()));
            file.write_all(line.as_bytes()).unwrap();
            std::thread::spawn(move || c.wait());
        }
    });
    out("READY");
    loop {
        std::thread::park();
    }
}

/// A process's creation time (FILETIME as one number).
fn created(process: RawHandle) -> u64 {
    let mut times = [FILETIME::default(); 4];
    let [c, e, k, u] = &mut times;
    // SAFETY: a process handle with query access and four valid out pointers.
    assert_ne!(unsafe { GetProcessTimes(process, c, e, k, u) }, 0);
    u64::from(c.dwHighDateTime) << 32 | u64::from(c.dwLowDateTime)

fn chain(level: u32, depth: &str, resist: &str, root_exits: &str) -> ! {
    if resist == "1" {
        // SAFETY: a handler that lives as long as the process.
        unsafe { SetConsoleCtrlHandler(Some(ignore_ctrl), 1) };
    }
    let mut next = (level < depth.parse().unwrap()).then(|| {
        child_cmd(&["chain", &(level + 1).to_string(), depth, resist, "0"])
            .spawn()
            .unwrap()
    });
    if level > 0 {
        out(&format!("PID {level} {}", std::process::id()));
    } else if root_exits == "1" {
        std::process::exit(0);
    } else {
        out("READY");
    }
    if let Some(c) = next.as_mut() {
        let _ = c.wait(); // never returns while the chain hangs
    }
    loop {
        std::thread::park();
    }

/// Pipe first (first instance, local clients only), then the supervisor on its own windowless console,
/// then the client-pid check and `Ready`.
pub fn start() -> Host {
    static N: AtomicU32 = AtomicU32::new(0);
    let name = format!(
        r"\\.\pipe\hugr-omni-test-{}-{}",
        std::process::id(),
        N.fetch_add(1, Ordering::Relaxed)
    );
    let wide: Vec<u16> = name.encode_utf16().chain([0]).collect();
    let open = PIPE_ACCESS_DUPLEX | FILE_FLAG_OVERLAPPED | FILE_FLAG_FIRST_PIPE_INSTANCE;
    let mode = PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT | PIPE_REJECT_REMOTE_CLIENTS;
    // SAFETY: a NUL-terminated name and null security attributes (not inheritable).
    let h = unsafe { CreateNamedPipeW(wide.as_ptr(), open, mode, 1, BUF, BUF, 0, std::ptr::null()) };
    let pipe = Arc::new(owned(h, "CreateNamedPipeW"));
    let sup = Command::new(env!("CARGO_BIN_EXE_hugr-omni-supervisor"))
        .args(["--host-pid", &std::process::id().to_string(), "--pipe", &name])
        .creation_flags(CREATE_NO_WINDOW)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .spawn()
        .unwrap();
    let raw = pipe.as_raw_handle();
    // SAFETY: `overlapped` keeps the OVERLAPPED alive until the operation completes.
    overlapped(&pipe, |ov| unsafe { ConnectNamedPipe(raw, ov) }, Some(T)).unwrap();
    let mut client = 0;
    // SAFETY: a connected pipe and a valid out pointer.
    check(unsafe { GetNamedPipeClientProcessId(raw, &mut client) }, "client pid");
    assert_eq!(client, sup.id(), "the pipe's client is not the supervisor we started");
    let (tx, frames) = mpsc::sync_channel(64); // a host that stops reading stalls the supervisor's writes
    let p = pipe.clone();
    std::thread::spawn(move || {
        let (mut buf, mut chunk) = (Vec::new(), vec![0u8; BUF as usize]);
        loop {
            match omni_proto::decode(&buf) {
                Ok(Some((m, n))) => {
                    buf.drain(..n);
                    if tx.send(m).is_err() {
                        return;
                    }
                }
                Ok(None) => {
                    let at = chunk.as_mut_ptr();
                    // SAFETY: as above; `chunk` outlives the read.
                    let read = |ov| unsafe { ReadFile(p.as_raw_handle(), at, BUF, std::ptr::null_mut(), ov) };
                    match overlapped(&p, read, None) {
                        Ok(n) if n > 0 => buf.extend_from_slice(&chunk[..n]),
                        _ => return,
                    }
                }
                Err(e) => panic!("the supervisor sent a malformed frame: {e}"),
            }
        }
    });

/// The first frame matching `want` (earlier ones are kept for later), within `T`.
pub fn recv(&mut self, what: &str, want: impl Fn(&Msg) -> bool) -> Msg {
    if let Some(i) = self.early.iter().position(&want) {
        return self.early.remove(i);
    }
    let end = Instant::now() + T;
    loop {
        match self.frames.recv_timeout(end.saturating_duration_since(Instant::now())) {
            Ok(m) if want(&m) => return m,
            Ok(m) => self.early.push(m),
            Err(e) => panic!("waiting for {what}: {e:?}; received meanwhile: {:?}", self.early),
        }
    }
}

/// The reply to request `req`.
pub fn reply(&mut self, req: u64) -> Msg {
    self.recv("a reply", |m| reply_to(m) == Some(req))
}

/// One request, its reply.
pub fn call(&mut self, make: impl FnOnce(u64) -> Msg) -> Msg {
    let req = self.req();
    self.send(&make(req));
    self.reply(req)
}

/// Hands a host-side handle to the supervisor (non-inheritable, `DUPLICATE_CLOSE_SOURCE`).
pub fn give(&self, h: OwnedHandle) -> u64 {
    let (sup, mut target) = (self.sup.as_raw_handle(), std::ptr::null_mut());
    let opts = DUPLICATE_SAME_ACCESS | DUPLICATE_CLOSE_SOURCE;
    // SAFETY: valid process handles; the source handle is closed by the call.
    let ok = unsafe {
        DuplicateHandle(
            GetCurrentProcess(),
            h.into_raw_handle(),
            sup,
            &mut target,
            0,
            FALSE,
            opts,
        )
    };
    check(ok, "give");
    target as u64

    /// Writes `Go` requests without reading any reply until one write stays pending for 2 s, i.e. the
    /// supervisor stopped reading; prints `STALLED` and never returns (the pending write stays alive).
    pub fn flood(&self, id: u64) -> ! {
        let mut req = 1 << 40;
        loop {
            req += 1;
            write_watching(&self.pipe, &frame(&Msg::Go { req, id }), Duration::from_secs(2), || {
                out("STALLED");
                loop {
                    std::thread::park();
                }
            });
        }
    }
}

impl Drop for Host {
    /// Whatever a test leaves behind dies with the supervisor's Jobs.
    fn drop(&mut self) {
        let _ = self.sup.kill();
    }

/// A host in its own process (so the test can kill it or give it its own console) with a resistant chain
/// (grace 500 ms), except in `console`. Prints `SUP <pid>` and `TREE <root> <pid 1> <pid 2>`, then:
/// `kill`: starts a `std::process` control child, prints `CONTROL <pid>` and waits to be killed;
/// `flood`: floods the channel (`Host::flood`);
/// `console`: counts console events, stops the tree gracefully, sends one CTRL_BREAK to its own console
/// as the control, prints `EVENTS <count> EXIT <root exit code> MS <stop time>`.
fn sub_host(kind: &str) -> ! {
    if kind == "console" {
        // SAFETY: a handler that lives as long as the process.
        unsafe { SetConsoleCtrlHandler(Some(count_ctrl), TRUE) };
    }
    let mut host = Host::start();
    let mut spec = Spec::child(&["chain", "0", "2", if kind == "console" { "0" } else { "1" }, "0"]);
    spec.grace_ms = 500;
    let tree = host.spawn(spec).unwrap();
    let pids: Vec<String> = tree
        .stdout
        .take("PID ", 2)
        .iter()
        .map(|l| l.rsplit(' ').next().unwrap().into())
        .collect();
    tree.stdout.line("READY");
    out(&format!("SUP {}", host.sup.id()));
    out(&format!("TREE {} {}", tree.pid, pids.join(" ")));
    match kind {
        "kill" => {
            let mut control = child_cmd(&["chain", "0", "0", "0", "0"])
                .stdout(Stdio::null())
                .spawn()
                .unwrap();
            out(&format!("CONTROL {}", control.id()));
            let _ = control.wait(); // the test kills this host first
        }
        "flood" => host.flood(tree.id),
        _ => {
            let ms = host.stop(tree.id, 5000).as_millis();
            let code = host.exited(tree.id);
            // SAFETY: plain call; group 0 = every process on this sub-host's own console.
            check(
                unsafe { GenerateConsoleCtrlEvent(CTRL_BREAK_EVENT, 0) },
                "GenerateConsoleCtrlEvent",
            );
            let n = *EVENT_SEEN
                .wait_timeout_while(EVENTS.lock().unwrap(), T, |n| *n == 0)
                .unwrap()
                .0;
            out(&format!("EVENTS {n} EXIT {code} MS {ms}"));
        }
    }
    std::process::exit(0)

impl Spec {
    /// `program args...` with this process's environment and cwd, stdin null, stderr piped.
    pub fn program(program: &Path, args: &[&str]) -> Spec {
        Spec {
            program: program.into(),
            argv: std::iter::once(program.as_os_str())
                .chain(args.iter().map(OsStr::new))
                .map(Into::into)
                .collect(),
            env: std::env::vars_os().collect(),
            cwd: std::env::current_dir().unwrap(),
            stdin: Slot::Null,
            stderr: Slot::Pipe,
            grace_ms: 1000,
            verbatim: None,
        }
    }

    /// The child program (`windows_child.rs`) in mode `args`.
    pub fn child(args: &[&str]) -> Spec {
        let all: Vec<&str> = CHILD.iter().chain(args).copied().collect();
        Spec::program(&std::env::current_exe().unwrap(), &all)
    }

/// A `Spawn` ready to send (its stdio handles already given to the supervisor) and the host's ends.
pub struct Prepared {
    /// Its request id.
    pub req: u64,
    /// The message.
    pub msg: Msg,
    stdout: OwnedHandle,
    stderr: Option<Lines>,
    stdin: Option<File>,
}

impl Host {
    /// The `Spawn` for `spec`, with fresh pipes for its stdio slots.
    pub fn prepare(&mut self, spec: Spec) -> Prepared {
        let (out_r, out_w) = pipe();
        let (stdin, in_h) = match spec.stdin {
            Slot::Pipe => {
                let (r, w) = pipe();
                (Some(File::from(w)), self.give(r))
            }
            _ => (None, 0),
        };
        let (stderr, err_h) = match spec.stderr {
            Slot::Pipe => {
                let (r, w) = pipe();
                (Some(Lines::new(File::from(r))), self.give(w))
            }
            _ => (None, 0),
        };
        let handles = [in_h, self.give(out_w), err_h];
        let bytes = |s: &OsStr| s.as_encoded_bytes().to_vec();
        let req = self.req();
        let msg = Msg::Spawn(Spawn {
            req,
            program: bytes(spec.program.as_os_str()),
            argv: spec.argv.iter().map(|a| bytes(a)).collect(),
            env: spec.env.iter().map(|(k, v)| (bytes(k), bytes(v))).collect(),
            cwd: bytes(spec.cwd.as_os_str()),
            pty: None,
            stdin: spec.stdin,
            stderr: spec.stderr,
            grace_ms: spec.grace_ms,
            handles,
            verbatim: spec.verbatim.as_deref().map(bytes),
        });
        Prepared {
            req,
            msg,
            stdout: out_r,
            stderr,
            stdin,
        }

/// Spawns `spec` with fresh pipes for its stdio slots.
pub fn spawn(&mut self, spec: Spec) -> Result<Tree, (FailCode, String)> {
    let p = self.prepare(spec);
    self.send(&p.msg);
    match self.reply(p.req) {
        Msg::Spawned {
            id,
            pid,
            pty_ends: [0, 0],
            ..
        } => {
            let (root, stdout) = (Proc::open(pid), Lines::new(File::from(p.stdout)));
            Ok(Tree {
                id,
                pid,
                root,
                stdout,
                stderr: p.stderr,
                stdin: p.stdin,
            })
        }
        Msg::SpawnFailed { code, msg, .. } => Err((code, msg)),
        other => panic!("unexpected reply to Spawn: {other:?}"),
    }

/// Runs one overlapped operation on `pipe` and waits for it (within `limit`, cancelling on timeout).
pub fn overlapped(
    pipe: &OwnedHandle,
    op: impl FnOnce(*mut OVERLAPPED) -> i32,
    limit: Option<Duration>,
) -> std::io::Result<usize> {
    let ev = event();
    let mut ov = OVERLAPPED {
        hEvent: ev.as_raw_handle(),
        ..Default::default()
    };
    if op(&mut ov) == 0 {
        let e = std::io::Error::last_os_error();
        match e.raw_os_error().map(|c| c as u32) {
            Some(ERROR_IO_PENDING | ERROR_MORE_DATA) => {}
            Some(ERROR_PIPE_CONNECTED) => return Ok(0),
            _ => return Err(e),
        }
    }
    let ms = limit.map_or(INFINITE, |d| d.as_millis() as u32);
    // SAFETY: a valid event and pipe; on timeout the operation is cancelled, then awaited below.
    unsafe {
        if WaitForSingleObject(ev.as_raw_handle(), ms) == WAIT_TIMEOUT {
            CancelIoEx(pipe.as_raw_handle(), &ov);
        }
    }
    let mut n = 0;
    // SAFETY: `ov` belongs to the operation above; waiting completes it before `ov` goes away.
    if unsafe { GetOverlappedResult(pipe.as_raw_handle(), &ov, &mut n, TRUE) } == 0 {
        let e = std::io::Error::last_os_error();
        if e.raw_os_error() != Some(ERROR_MORE_DATA as i32) {
            return Err(e);
        }
    }
    Ok(n as usize)

/// Writes `bytes` to `pipe`; if the write is still pending after `stall` (the reader stopped reading), calls
/// `on_stall` once, then waits for the write to complete.
pub fn write_watching(pipe: &OwnedHandle, bytes: &[u8], stall: Duration, on_stall: impl FnOnce()) {
    let ev = event();
    let mut ov = OVERLAPPED {
        hEvent: ev.as_raw_handle(),
        ..Default::default()
    };
    // SAFETY: `bytes` and `ov` outlive the write: it is awaited below (or `on_stall` never returns).
    let ok = unsafe {
        WriteFile(
            pipe.as_raw_handle(),
            bytes.as_ptr(),
            bytes.len() as u32,
            std::ptr::null_mut(),
            &mut ov,
        )
    };
    if ok == 0 {
        let e = std::io::Error::last_os_error();
        assert_eq!(e.raw_os_error(), Some(ERROR_IO_PENDING as i32), "write: {e}");
        // SAFETY: a valid event.
        if unsafe { WaitForSingleObject(ev.as_raw_handle(), stall.as_millis() as u32) } == WAIT_TIMEOUT {
            on_stall();
        }
    }
    let mut n = 0;
    // SAFETY: `ov` belongs to the write above.
    check(
        unsafe { GetOverlappedResult(pipe.as_raw_handle(), &ov, &mut n, TRUE) },
        "write",
    );
    assert_eq!(n as usize, bytes.len());

/// The OS-only oracle: the process that had `pid` and was created at `born` is gone (no process has the pid,
/// another process has it now, or it has exited).
pub fn gone(pid: u32, born: u64) -> bool {
    // SAFETY: a plain open by pid.
    let h = unsafe { OpenProcess(PROCESS_SYNCHRONIZE | PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid) };
    if h.is_null() {
        let e = std::io::Error::last_os_error();
        assert_eq!(
            e.raw_os_error(),
            Some(ERROR_INVALID_PARAMETER as i32),
            "OpenProcess({pid}): {e}"
        );
        return true;
    }
    let h = owned(h, "OpenProcess");
    // SAFETY: a valid process handle.
    created(&h) != born || unsafe { WaitForSingleObject(h.as_raw_handle(), 0) } == WAIT_OBJECT_0

impl Lines {
    /// Starts reading `r`.
    pub fn new(r: impl Read + Send + 'static) -> Lines {
        let (tx, rx) = mpsc::channel();
        std::thread::spawn(move || {
            for line in BufReader::new(r).split(b'\n').map_while(Result::ok) {
                if tx
                    .send(String::from_utf8_lossy(&line).trim_end_matches('\r').to_string())
                    .is_err()
                {
                    return;
                }
            }
        });
        Lines {
            rx,
            kept: Default::default(),
        }

/// Not exited.
pub fn alive(&self) -> bool {
    // SAFETY: a valid process handle.
    unsafe { WaitForSingleObject(self.0.as_raw_handle(), 0) == WAIT_TIMEOUT }
}

/// Exits within `d`.
pub fn dead_within(&self, d: Duration) -> bool {
    // SAFETY: a valid process handle.
    unsafe { WaitForSingleObject(self.0.as_raw_handle(), d.as_millis() as u32) == WAIT_OBJECT_0 }
}

/// Its exit code.
pub fn exit_code(&self) -> u32 {
    let mut code = 0;
    // SAFETY: a process handle with query access.
    check(
        unsafe { GetExitCodeProcess(self.0.as_raw_handle(), &mut code) },
        "GetExitCodeProcess",
    );
    code
}

/// Whether it holds, at value `value`, a handle to the same object as `ours`.
pub fn holds(&self, value: usize, ours: &OwnedHandle) -> bool {
    let (from, mut dup) = (self.0.as_raw_handle(), std::ptr::null_mut());
    // SAFETY: valid process handles (`from` has PROCESS_DUP_HANDLE); a failed duplicate leaves `dup` null.
    let ok = unsafe {
        DuplicateHandle(
            from,
            value as HANDLE,
            GetCurrentProcess(),
            &mut dup,
            0,
            FALSE,
            DUPLICATE_SAME_ACCESS,
        )
    };
    // SAFETY: two valid handles.
    ok != 0 && unsafe { CompareObjectHandles(owned(dup, "dup").as_raw_handle(), ours.as_raw_handle()) } != 0

