            value as HANDLE,
            GetCurrentProcess(),
            &mut h,
            0,
            FALSE,
            DUPLICATE_SAME_ACCESS | DUPLICATE_CLOSE_SOURCE,
        )
    };
    check(ok, "pull a terminal end");
